CREATE TABLE project_addendum_history (project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, source_run_id TEXT NOT NULL, record_json TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(project_id,source_run_id));
CREATE TABLE desktop_addendum_imports (owner_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, request_id TEXT NOT NULL, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, content_hash TEXT NOT NULL, mutation_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(owner_id,request_id));
